const collection = useAsyncCollection<ProjectRecord, string>({
  initialQuery: '',
  load: query => getRecords(query),
  getKey: record => record.id,
  isFiltered: query => query.trim().length > 0,
  selection: 'clear-on-query',
  messages: {
    loading: 'Loading project records',
    refreshing: 'Refreshing project records',
    empty: 'No project records are available',
    noResults: 'No project records match your search',
    failed: 'We couldn’t load the project records. Try again.',
    results: count => `${count} project ${count === 1 ? 'record' : 'records'} found`,
  },
});
const isWorking = collection.phase === 'loading' || collection.phase === 'refreshing';
const hasSearch = collection.query.length > 0;
const sortedItems = React.useMemo(() => {
  const direction = sortDirection === 'ascending' ? 1 : -1;
  return [...collection.items].sort((left, right) => {
    const byName = left.name.localeCompare(right.name, undefined, {numeric: true, sensitivity: 'base'});
    return (byName || left.id.localeCompare(right.id)) * direction;
  });
}, [collection.items, sortDirection]);

React.useEffect(() => {
  const id = ++requestId.current;
  const retainingRecords = refreshKey > 0 && records !== undefined;
  if (retainingRecords) {
    setIsRefreshing(true);
    setAnnouncement('Refreshing project records');
  } else {
    setRecords(undefined);
    setAnnouncement('Loading project records');
  }
  setError(null);

  getRecords(committedQuery)
    .then((nextRecords) => {
      if (id !== requestId.current) return;
      setRecords(nextRecords);
      setSelected((ids) => ids.filter((selectedId) => nextRecords.some((record) => record.id === selectedId)));
      setAnnouncement(`${nextRecords.length} project record${nextRecords.length === 1 ? '' : 's'} found${committedQuery ? ` for ${committedQuery}` : ''}`);
    })
    .catch((reason: unknown) => {
      if (id !== requestId.current) return;
      const message = reason instanceof Error ? reason.message : 'Could not load project records';
      setError(message);
      setAnnouncement(`Project records could not be loaded. ${message}`);
    })
    .finally(() => {
      if (id === requestId.current) setIsRefreshing(false);
    });
// refreshKey intentionally repeats the current request.
// eslint-disable-next-line react-hooks/exhaustive-deps
}, [committedQuery, refreshKey]);

function updateQuery(value: string) {
  requestId.current += 1;
  setQuery(value);
  setRecords(undefined);
  setError(null);
  setSelected([]);
}

const loadRecords = React.useCallback(async (search: string, refresh = false) => {
  const request = ++requestNumber.current;
  setError(undefined);
  if (refresh) setIsRefreshing(true);
  else setRecords(undefined);
  try {
    const nextRecords = await getRecords(search);
    if (request === requestNumber.current) setRecords(nextRecords);
  } catch (reason) {
    if (request === requestNumber.current) {
      setError(reason instanceof Error ? reason.message : 'Could not load records.');
      setRecords([]);
    }
  } finally {
    if (request === requestNumber.current) setIsRefreshing(false);
  }
}, []);

{error && (
  <Alert className="load-error" tone="critical" title="Records couldn’t be loaded" action={<Button size="sm" variant="secondary" onClick={() => void loadRecords(query)}>Try again</Button>}>
    {error}
  </Alert>
)}

