const form = useEditRecord<Workspace>({
  initialValue: workspace,
  validationMode: 'submit',
  validate: value => {
    const errors: Partial<Record<keyof Workspace, string>> = {};
    if (!value.name.trim()) errors.name = 'Enter a workspace name.';
    if (!value.email.trim()) errors.email = 'Enter a contact email.';
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.email.trim())) errors.email = 'Enter a valid email address, such as name@example.com.';
    return errors;
  },
  save: async draft => {
    try {
      const saved = await saveWorkspace({ ...draft, name: draft.name.trim(), description: draft.description?.trim() || '', email: draft.email.trim() });
      onSaved(saved);
      return { ok: true, value: saved };
    } catch (error) {
      return { ok: false, error: error instanceof Error ? error.message : 'The workspace could not be saved. Try again.' };
    }
  },
  messages: { saving: 'Saving workspace settings…', saved: 'Workspace settings saved.', failed: 'Workspace settings could not be saved.', invalid: 'Check the highlighted fields and try again.', newerEdits: 'Your earlier changes were saved. Save again to keep your newest changes.' },
});

React.useEffect(() => {
