function useRecordCollection(query: string) {
  const [state, setState] = React.useState<CollectionState>({
    records: null, loadedQuery: '', updatedAt: null, pending: 'initial', error: null,
  });
  const latest = React.useRef(0);

  const load = React.useCallback((q: string, mode: Mode) => {
    // A newer request invalidates any response still in flight.
    const id = ++latest.current;
    setState(s => ({...s, pending: mode, error: null}));
    getRecords(q).then(
      records => {
        if (id !== latest.current) return;
        setState({records, loadedQuery: q, updatedAt: new Date(), pending: null, error: null});
      },
      (err: unknown) => {
        if (id !== latest.current) return;
        const message = err instanceof Error ? err.message : 'Request failed';
        setState(s => ({...s, pending: null, error: message}));
      },
    );
  }, []);

  const first = React.useRef(true);
  React.useEffect(() => {
    load(query, first.current ? 'initial' : 'search');
    first.current = false;
  }, [query, load]);

  const {records, loadedQuery, pending, error} = state;
  let phase: Phase;
  if (records === null) phase = error ? 'failed' : 'loading';
  else if (pending) phase = pending === 'refresh' ? 'refreshing' : 'loading';
  else if (error) phase = 'failed';
  else if (records.length > 0) phase = 'populated';
  else phase = loadedQuery ? 'no-results' : 'empty';

  return {
    ...state,
    phase,
    refresh: () => load(query, 'refresh'),
    // Retry repeats the current request.
    retry: () => load(query, 'retry'),
  };
}

{c.phase === 'failed' && (
