// Plain errors thrown by request() carry the server's message; network and parse failures do not.
const serviceMessage = (error: unknown) =>
  error instanceof Error && error.name === 'Error' && error.message && error.message !== 'Request failed' ? error.message : '';

function App() {
  const [route, setRoute] = React.useState<Route>(() => routeFromHash(location.hash));
  const [load, setLoad] = React.useState<Load>({status: 'loading'});
  const routeRef = React.useRef(route);
  const guard = React.useRef<LeaveGuard | null>(null);
  const returnFocus = React.useRef(false);

  const fetchWorkspace = React.useCallback(() => {
    let current = true;
    setLoad({status: 'loading'});
    getWorkspace().then(
      workspace => { if (current) setLoad({status: 'ready', workspace}); },
      error => {
        if (!current) return;
        const detail = serviceMessage(error);
        setLoad({status: 'failed', error: detail ? `We couldn’t load the workspace: ${detail}` : 'We couldn’t load the workspace. Check your connection and try again.'});
      });
    return () => { current = false; };
  }, []);
  React.useEffect(fetchWorkspace, [fetchWorkspace]);

  const show = (next: Route) => {
    if (routeRef.current === 'settings' && next === 'overview') returnFocus.current = true;
    routeRef.current = next;
    setRoute(next);
  };

  // In-app navigation. `guarded: false` is for callers that already resolved the leave decision (Cancel).
  const navigate = async (next: Route, {guarded = true} = {}) => {
    if (next === routeRef.current) return;
    if (guarded && routeRef.current === 'settings' && guard.current && !(await guard.current('navigation'))) return;
    history.pushState(null, '', hashFor(next));
    show(next);
  };

  // Browser Back/Forward and edited URLs: the URL has already changed, so restore it if the person keeps editing.
  React.useEffect(() => {
    const onHashChange = async () => {
      const next = routeFromHash(location.hash);
      if (next === routeRef.current) return;
      if (routeRef.current === 'settings' && guard.current && !(await guard.current('back'))) {
        history.pushState(null, '', hashFor('settings'));
        return;
      }
      show(next);
    };
    addEventListener('hashchange', onHashChange);
    return () => removeEventListener('hashchange', onHashChange);
  }, []);

const form = useEditRecord<WorkspaceDraft>({
  initialValue: toDraft(initialValue),
  validationMode: 'submit',
  validate,
  // An empty description is sent as "" so clearing the field clears the saved description.
  save: async (draft): Promise<EditRecordResult<WorkspaceDraft>> => {
    try {
      const saved = await saveWorkspace({name: draft.name.trim(), email: draft.email.trim(), description: draft.description.trim()});
      onSaved(saved);
      return {ok: true, value: toDraft(saved)};
    } catch (error) {
      const detail = serviceMessage(error);
      return {ok: false, error: detail ? `We couldn’t save the workspace settings: ${detail}` : 'We couldn’t save the workspace settings. Check your connection and try again.'};
    }
  },
  messages: {
    saving: 'Saving workspace settings…',
    saved: 'Workspace settings saved.',
    invalid: 'Check the highlighted fields.',
    newerEdits: 'Your earlier changes were saved. Your newer edits still need saving.',
  },
});
const submitting = form.phase === 'submitting';

React.useEffect(() => { heading.current?.focus(); }, []);

// Back and in-app navigation go through the same discard decision as Cancel.
const requestLeave = form.requestLeave;
React.useEffect(() => {
