};

/** A real discard decision: resolves true only when the person chooses to discard. */
function useDiscardConfirmation(): [React.ReactNode, () => Promise<boolean>] {
  const [open, setOpen] = React.useState(false);
  const resolver = React.useRef<((discard: boolean) => void) | null>(null);
  const settle = (discard: boolean) => {
    resolver.current?.(discard);
    resolver.current = null;
    setOpen(false);
  };
  React.useEffect(() => () => resolver.current?.(false), []);
  const confirm = React.useCallback(() => new Promise<boolean>(resolve => {
    resolver.current?.(false);
    resolver.current = resolve;
    setOpen(true);
  }), []);
  const dialog = (
    <Dialog
      open={open}
      onOpenChange={next => { if (!next) settle(false); }}
      dismissible={false}
      size="sm"
      title="Discard unsaved changes?"
      description="Your changes to the workspace settings haven’t been saved."
      focusSelector="[data-autofocus]"
      footer={<div style={actions}>
        <Button data-autofocus variant="secondary" onClick={() => settle(false)}>Keep editing</Button>
        <Button variant="danger" onClick={() => settle(true)}>Discard changes</Button>
      </div>}
    />
  );
  return [dialog, confirm];
}

// Warn before the page itself is closed or reloaded with unsaved edits.
React.useEffect(() => {
  if (!dirty) return;
  const warn = (e: BeforeUnloadEvent) => { e.preventDefault(); e.returnValue = ''; };
  window.addEventListener('beforeunload', warn);
  return () => window.removeEventListener('beforeunload', warn);
}, [dirty]);

// Move focus to the summary on every invalid submit.
