const change = (key: keyof Draft) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
  const value = e.target.value;
  setDraft((d) => ({...d, [key]: value}));
  setStatus('');
};

const submit = async () => {
  if (pendingRef.current || !baseline) return;
  const submitted = draftRef.current;
  const found = validate(submitted);
  setErrors(found);
  if (Object.keys(found).length) {
    setStatus('');
    setSubmitCount((n) => n + 1);
    return;
  }
  pendingRef.current = true;
  setPending(true);
  setFailure(null);
  setStatus('Saving settings…');
  try {
    const saved = await saveWorkspace({...baseline, name: submitted.name.trim(), email: submitted.email.trim(), description: submitted.description.trim()});
    setBaseline(saved);
    // Only adopt the server's canonical value if nothing was typed while saving.
    if (sameDraft(draftRef.current, submitted)) setDraft(toDraft(saved));
    setStatus('Settings saved.');
    onSaved(saved);
  } catch (e) {
    setFailure(message(e));
    setStatus('');
  } finally {
    pendingRef.current = false;
    setPending(false);
  }
};

const requestLeave = () => {
  if (pendingRef.current) return;
  if (dirty) setConfirmOpen(true);
  else onLeave();
};

const discard = () => {
  setConfirmOpen(false);
  onLeave();
};

