/** Moves focus to the view's heading when the view appears, so keyboard and screen reader users land in the new view. */
function useFocusOnMount<T extends HTMLElement>() {
  const ref = React.useRef<T>(null);
  React.useEffect(() => { ref.current?.focus(); }, []);
  return ref;
}

