async function submit(event: React.FormEvent) {
  event.preventDefault();
  setSubmitted(true);
  if (nameError || emailError || descriptionError || saving) return;
  setSaving(true);
  setSaveError(null);
  try {
    // Spread first so any fields this screen doesn't edit stay intact.
    const saved = await saveWorkspace({...workspace, name: name.trim(), email: email.trim(), description: description.trim()});
    onSaved(saved);
