    setSaveError(error instanceof Error ? error.message : 'Request failed');
    setSaving(false);
  }
}

const collection = useAsyncCollection<ProjectRecord, string>({
  initialQuery: '',
  load: query => getRecords(query.trim()),
  getKey: record => record.id,
  isFiltered: query => !!query.trim(),
  selection: 'preserve',
  messages: {
    loading: 'Loading project records',
    refreshing: 'Refreshing project records',
    empty: 'No project records yet',
    noResults: 'No project records match this name',
