// Selection is preserved across searches, so remember names for selected records that leave the current view.
const [knownNames, setKnownNames] = React.useState<ReadonlyMap<string, string>>(new Map());
// Failed loads keep the previous items; track which query those items belong to.
const [loadedQuery, setLoadedQuery] = React.useState<string | null>(null);
React.useEffect(() => {
  if (collection.phase === 'populated' || collection.phase === 'empty' || collection.phase === 'no-results') {
    setLoadedQuery(collection.query);
    if (collection.items.length) setKnownNames(previous => {
      const next = new Map(previous);
      for (const record of collection.items) next.set(record.id, record.name);
      return next;
    });
  }
}, [collection.phase, collection.items, collection.query]);

const load = React.useCallback((q: string) => {
  const id = ++requestId.current;
  const prior = loadedRef.current;
  setPhase(prior && prior.query === q ? 'refreshing' : 'loading');
  setStatus(prior && prior.query === q ? 'Refreshing records…' : 'Loading records…');
  getRecords(q).then(
    records => {
      if (id !== requestId.current) return; // a newer query or refresh superseded this response
      const searching = q.trim() !== '';
      setLoaded({query: q, records, at: new Date()});
      setError(null);
      setPhase(records.length ? 'populated' : searching ? 'no-results' : 'empty');
      let removed = 0;
      if (!searching) {
        // An unfiltered load is the full set: drop selections whose records no longer exist.
        const ids = new Set(records.map(r => r.id));
        const prev = selectedRef.current;
        const next = new Map([...prev].filter(([key]) => ids.has(key)));
        removed = prev.size - next.size;
        if (removed) setSelected(next);
      }
      const summary = searching ? `${plural(records.length, 'record')} match “${q.trim()}”.` : `${plural(records.length, 'record')}.`;
      setStatus(removed ? `${summary} ${plural(removed, 'selected record')} no longer exist and were deselected.` : summary);
    },
    (e: unknown) => {
      if (id !== requestId.current) return;
      const message = e instanceof Error ? e.message : 'Request failed';
      setError(message);
      setPhase('failed');
      setStatus(`Records could not be loaded: ${message}`);
    },
  );
}, []);

{error && (
