function useDiscardConfirmation() {
  const [open, setOpen] = React.useState(false);
  const resolver = React.useRef<((discard: boolean) => void) | null>(null);
  const answer = (discard: boolean) => { resolver.current?.(discard); resolver.current = null; setOpen(false); };
  const confirm = () => new Promise<boolean>(resolve => { resolver.current = resolve; setOpen(true); });
  const dialog = <Dialog open={open} onOpenChange={next => { if (!next) answer(false); }} size="sm" initialFocus="title"
    title="Discard unsaved changes?" description="Your changes to the workspace settings haven’t been saved."
    footer={<>
      <Button variant="secondary" onClick={() => answer(false)}>Keep editing</Button>
      <Button variant="danger" onClick={() => answer(true)}>Discard changes</Button>
    </>} />;
  return {confirm, dialog};
}

const form = useEditRecord<Workspace>({
  initialValue,
  validationMode: 'submit',
  validate,
  messages: {saving: 'Saving workspace settings', saved: 'Workspace settings saved'},
  save: async (draft): Promise<EditRecordResult<Workspace>> => {
    try {
      // An empty description is sent as '' so clearing the field clears the stored value.
      const saved = await saveWorkspace({...draft, name: draft.name.trim(), email: draft.email.trim(), description: (draft.description ?? '').trim()});
      onSaved(saved);
      return {ok: true, value: editable(saved)};
    } catch (error) {
      const detail = error instanceof Error && error.message ? ` ${error.message}.` : '';
      return {ok: false, error: `We couldn’t save the workspace settings.${detail} Check your changes and try again.`};
    }
  },
});

// Reloading or closing the tab can't use the in-app dialog; ask the browser to warn instead.
const unsaved = form.dirty || form.phase === 'submitting';
React.useEffect(() => {
  if (!unsaved) return;
  const warn = (event: BeforeUnloadEvent) => { event.preventDefault(); event.returnValue = ''; };
  window.addEventListener('beforeunload', warn);
  return () => window.removeEventListener('beforeunload', warn);
}, [unsaved]);

const cancel = async () => { if (await form.requestLeave('cancel', discard.confirm)) onLeave(); };

const update = (key: keyof Draft) => (event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
  const value = event.target.value;
  draftVersion.current += 1;
  setDraft(current => ({...current, [key]: value}));
  setStatus('');
};

async function submit(event: React.FormEvent) {
  event.preventDefault();
  if (savingRef.current) return;
  const nextErrors = validate(draft);
  setErrors(nextErrors);
  if (Object.keys(nextErrors).length) {
    setStatus('');
    setSummaryAttempt(n => n + 1);
    return;
  }
  savingRef.current = true;
  setSaving(true);
  setFailure(null);
  setStatus('Saving workspace settings…');
  const submittedVersion = draftVersion.current;
  try {
    const saved = await saveWorkspace({...baseline, name: draft.name.trim(), email: draft.email.trim(), description: draft.description.trim()});
    setBaseline(saved);
    // Never let the response for an older draft overwrite newer input.
    if (draftVersion.current === submittedVersion) setDraft(toDraft(saved));
    setStatus('Workspace settings saved.');
  } catch (error) {
    setFailure(errorMessage(error));
    setStatus('Workspace settings were not saved.');
  } finally {
    savingRef.current = false;
    setSaving(false);
  }
}

const hasUnsavedWork = () => routeRef.current === 'settings' && !!formRef.current && (formRef.current.isDirty() || formRef.current.isSaving());

// Single leave check used by Cancel, in-app links and browser Back/Forward.
const navigate = React.useCallback((to: Route) => {
  if (to === routeRef.current) return;
  if (hasUnsavedWork()) { setPendingLeave(to); return; }
  if (location.hash !== ROUTES[to]) history.pushState(null, '', ROUTES[to]);
  setRoute(to);
}, []);

React.useEffect(() => {
  const onHashChange = () => {
    const to = routeFromHash();
    if (to === routeRef.current) return;
    if (hasUnsavedWork()) {
      // Put the address back until the person decides.
      history.pushState(null, '', ROUTES[routeRef.current]);
      setPendingLeave(to);
      return;
    }
    setRoute(to);
  };
  const onBeforeUnload = (event: BeforeUnloadEvent) => {
    if (hasUnsavedWork()) { event.preventDefault(); event.returnValue = ''; }
  };
  window.addEventListener('popstate', onHashChange);
  window.addEventListener('beforeunload', onBeforeUnload);
  return () => {
    window.removeEventListener('popstate', onHashChange);
    window.removeEventListener('beforeunload', onBeforeUnload);
  };
}, []);

const confirmLeave = () => {
  const to = pendingLeave;
  setPendingLeave(null);
  if (!to) return;
  if (location.hash !== ROUTES[to]) history.pushState(null, '', ROUTES[to]);
  setRoute(to);
};

async function submit(event: React.FormEvent) {
  event.preventDefault();
  setSubmitted(true);
  setSaveError(null);
  if (Object.keys(errors).length) return;
  setSaving(true);
  try {
    // Keep any fields this screen doesn't edit intact. A cleared description is sent as '' so the removal is saved.
    const saved = await saveWorkspace({...workspace, name: draft.name.trim(), email: draft.email.trim(), description: (draft.description ?? '').trim()});
    onSaved(saved);
  } catch (error) {
    setSaveError(error instanceof Error ? error.message : 'The workspace could not be saved.');
    setSaving(false);
  }
}

const collection = useAsyncCollection<ProjectRecord, string>({
  initialQuery: '',
  // getRecords takes no signal; the hook discards responses for superseded queries.
  load: query => getRecords(query),
  getKey: record => record.id,
  isFiltered: query => query.trim() !== '',
  // Selection survives searching so people can search for and pick several records.
  selection: 'preserve',
  messages: {
    loading: 'Loading records',
    refreshing: 'Updating records',
    empty: 'No project records yet',
    noResults: 'No records match this name',
    failed: 'We couldn’t load the records. Try again.',
    results: count => `${count} ${count === 1 ? 'record' : 'records'}`,
  },
});
const {phase, items, query, selectedKeys} = collection;
const searchRef = React.useRef<HTMLInputElement>(null);
const [text, setText] = React.useState(query);
const [sortOrder, setSortOrder] = React.useState<SortOrder>('name-asc');

// getRecords returns the full matching list, so ordering is done here; ties fall back to id to stay stable across refreshes.
const sortedItems = React.useMemo(() => {
  const direction = sortOrder === 'name-asc' ? 1 : -1;
  return [...items].sort((a, b) => direction * (nameCollator.compare(a.name, b.name) || a.id.localeCompare(b.id)));
}, [items, sortOrder]);

// Debounce typed text into the collection query.
React.useEffect(() => {
  if (text === query) return;
  const timer = window.setTimeout(() => collection.setQuery(text), SEARCH_DELAY_MS);
  return () => window.clearTimeout(timer);
}, [text]);

// Names of selected records, kept so selections hidden by the current search can still be listed.
const names = React.useRef(new Map<string, string>());
for (const record of items) names.current.set(record.id, record.name);

// The query whose results are on screen, so a failed request can say which results are retained.
const [shownQuery, setShownQuery] = React.useState<string | null>(null);
React.useEffect(() => {
  if (phase === 'populated' || phase === 'empty' || phase === 'no-results') setShownQuery(query);
}, [phase]);

const clearSearch = () => {
  setText('');
  collection.reset();
  searchRef.current?.focus();
};

const busy = phase === 'loading' || phase === 'refreshing';
const visibleKeys = new Set(items.map(record => record.id));
const hiddenSelected = [...selectedKeys].filter(key => !visibleKeys.has(key) || phase === 'no-results' || phase === 'empty');
const hasRetained = phase === 'failed' && shownQuery !== null;

function useRecords(query: string) {
  const [records, setRecords] = React.useState<ProjectRecord[] | null>(null);
  const [loadedQuery, setLoadedQuery] = React.useState('');
  const [pending, setPending] = React.useState(true);
  const [error, setError] = React.useState<string | null>(null);
  const latest = React.useRef(0);

  const load = React.useCallback((q: string) => {
    const id = ++latest.current;
    setPending(true);
    getRecords(q).then(
      result => {
        if (id !== latest.current) return;
        setRecords(result);
        setLoadedQuery(q);
        setError(null);
        setPending(false);
      },
      (reason: unknown) => {
        if (id !== latest.current) return;
        setError(reason instanceof Error ? reason.message : 'Request failed');
        setPending(false);
      },
    );
  }, []);

  React.useEffect(() => load(query), [query, load]);
  const retry = React.useCallback(() => load(query), [query, load]);

  let phase: Phase;
  if (records === null) phase = error && !pending ? 'failed' : 'loading';
  else if (pending) phase = 'refreshing';
  else if (error) phase = 'failed';
  else if (records.length > 0) phase = 'populated';
  else phase = loadedQuery === '' ? 'empty' : 'no-results';

  return {records, loadedQuery, phase, error, pending, retry};
}

React.useEffect(() => {
  let current = true;
  setLoading(true);
  setError(null);
  getRecords(search)
    .then((rows) => {
      if (current) setRecords(rows);
    })
    .catch((e: unknown) => {
      if (current) setError(e instanceof Error ? e.message : 'Could not load records');
    })
    .finally(() => {
      if (current) setLoading(false);
    });
  return () => {
    current = false;
  };
}, [search, reloadKey]);

