/>

/** The service's own error text, if any; parse and network errors aren't meaningful to people. */
const serviceMessage = (error: unknown) =>
  error instanceof Error && !(error instanceof SyntaxError) && !(error instanceof TypeError) && error.message !== 'Request failed'
    ? error.message : '';

/** Resolves with the person's decision; refusing keeps the draft. */
function useDiscardConfirmation() {
  const [pending, setPending] = React.useState<{resolve: (discard: boolean) => void} | null>(null);
  const confirm = React.useCallback(() => new Promise<boolean>(resolve => setPending({resolve})), []);
  const answer = (discard: boolean) => { pending?.resolve(discard); setPending(null); };
  const dialog = <Dialog open={!!pending} onOpenChange={open => { if (!open) answer(false); }} size="sm"
    title="Discard unsaved changes?" description="Your changes to the workspace settings haven’t been saved."
    footer={<>
      <Button variant="secondary" onClick={() => answer(false)}>Keep editing</Button>
      <Button variant="danger" onClick={() => answer(true)}>Discard changes</Button>
    </>} />;
  return {confirm, dialog};
}

const form = useEditRecord<Workspace>({
  // A missing description edits as empty text, so an untouched form stays clean.
  initialValue: {...workspace, description: workspace.description ?? ''},
  validationMode: 'submit',
  validate,
  messages: {saving: 'Saving workspace settings…', saved: 'Workspace settings saved.'},
  save: async (draft): Promise<EditRecordResult<Workspace>> => {
    try {
      // Send the whole record; an empty description is sent as '' so clearing it is explicit.
      const saved = await saveWorkspace({
        ...draft, name: draft.name.trim(), email: draft.email.trim(), description: (draft.description ?? '').trim(),
      });
      onSaved(saved);
      return {ok: true, value: saved};
    } catch (error) {
      const reason = serviceMessage(error);
      return {ok: false, error: `We couldn’t save the workspace settings.${reason && ` ${reason}`} Your changes are still here; try saving again.`};
    }
  },
});
const leave = (reason: LeaveReason) => form.requestLeave(reason, () => discard.confirm());
React.useImperativeHandle(handle, () => ({requestLeave: leave}));

React.useEffect(() => {
  if (!form.dirty && form.phase !== 'submitting') return;
  // Browsers show their own generic text and may not fire this in every lifecycle case.
  const warn = (event: BeforeUnloadEvent) => { event.preventDefault(); event.returnValue = ''; };
  addEventListener('beforeunload', warn);
  return () => removeEventListener('beforeunload', warn);
}, [form.dirty, form.phase]);

React.useEffect(() => {
  const onHashChange = async () => {
    const next = routeFromHash();
    if (next === routeRef.current) return;
    if (routeRef.current === 'settings' && settings.current) {
      history.pushState(null, '', hashFor('settings'));
      if (!(await settings.current.requestLeave('back'))) {
        setNotice('You’re still editing workspace settings.');
        return;
      }
      history.replaceState(null, '', hashFor(next));
    }
    setNotice('');
    setRoute(next);
  };
  addEventListener('hashchange', onHashChange);
  return () => removeEventListener('hashchange', onHashChange);
}, []);

const commit = React.useCallback((to: Route) => {
  if (location.hash !== routeHash[to]) history.pushState(null, '', routeHash[to]);
  setRoute(to);
}, []);

const navigate = React.useCallback((to: Route) => {
  if (routeRef.current === 'settings' && to !== 'settings' && guard.current) guard.current(() => commit(to));
  else commit(to);
}, [commit]);

// Browser Back/Forward: the hash has already changed, so put settings back while the guard decides.
React.useEffect(() => {
  const onHashChange = () => {
    const to = readRoute();
    if (routeRef.current === 'settings' && to !== 'settings' && guard.current) {
      history.replaceState(null, '', routeHash.settings);
      guard.current(() => commit(to));
    } else setRoute(to);
  };
  window.addEventListener('hashchange', onHashChange);
  return () => window.removeEventListener('hashchange', onHashChange);
}, [commit]);

// Move focus to the new view's heading so keyboard and screen reader users land in context.
const heading = React.useRef<HTMLHeadingElement>(null);
const firstRender = React.useRef(true);
React.useEffect(() => {
  if (firstRender.current) {firstRender.current = false; return;}
  heading.current?.focus();
}, [route]);

// One leave check for Cancel, browser Back and any other in-app navigation.
const requestLeave = React.useCallback<LeaveGuard>(proceed => {
  if (inFlight.current) {
    setStatus('Settings are still saving. You can leave once the save finishes.');
    return;
  }
  if (!dirty) proceed();
  else setPendingLeave(() => proceed);
}, [dirty]);
React.useEffect(() => {
  guard.current = requestLeave;
  return () => {guard.current = null;};
}, [guard, requestLeave]);

// Reload/close: browsers show their own wording; this only asks them to warn.
React.useEffect(() => {
  if (!dirty && !submitting) return;
  const onBeforeUnload = (event: BeforeUnloadEvent) => {event.preventDefault(); event.returnValue = '';};
  window.addEventListener('beforeunload', onBeforeUnload);
  return () => window.removeEventListener('beforeunload', onBeforeUnload);
}, [dirty, submitting]);

React.useEffect(() => {
  if (summaryFocus) summary.current?.focus();
}, [summaryFocus]);

const update = (key: keyof Draft) => (event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
  const value = event.target.value;
  setDraft(d => ({...d, [key]: value}));
  if (phase === 'saved') {setPhase('editing'); setStatus('');}
};

const submit = async () => {
  if (inFlight.current) return;
  const submitted = draftRef.current;
  const found = validate(submitted);
  setErrors(found);
  if (Object.keys(found).length) {
    setPhase('invalid');
    setStatus('');
    setSummaryFocus(n => n + 1);
    return;
  }
  inFlight.current = true;
  setPhase('submitting');
  setFailure('');
  setStatus('Saving settings…');
  try {
    // Spread the baseline so any fields this screen doesn't edit are sent back unchanged.
    const next: Workspace = {...baseline, name: submitted.name.trim(), email: submitted.email.trim()};
    // Clearing sends an empty string; a workspace that never had a description keeps it absent.
    const description = submitted.description.trim();
    if (description || baseline.description !== undefined) next.description = description;
    const saved = await saveWorkspace(next);
    onSaved(saved);
    if (!mounted.current) return;
    setBaseline(saved);
    // Only adopt the server's canonical values if nobody typed while the save was in flight.
    if (sameDraft(draftRef.current, submitted)) setDraft(toDraft(saved));
    setPhase('saved');
    setStatus('Settings saved.');
  } catch (error) {
    if (!mounted.current) return;
    setPhase('failed');
    setFailure(error instanceof Error ? error.message : 'Request failed');
    setStatus('');
  } finally {
    inFlight.current = false;
  }
};

async function submit(e: React.FormEvent) {
  e.preventDefault();
  setSubmitted(true);
  if (nameError || emailError || saving) return;
  setSaving(true);
  setSaveError(null);
  try {
    // Spread the loaded workspace so fields this screen doesn't edit are preserved.
    const saved = await saveWorkspace({...workspace, name: name.trim(), email: email.trim(), description: description.trim()});
    toast({title: 'Workspace settings saved', tone: 'positive'});
    onSaved(saved);
  } catch (err) {
    setSaveError(errorMessage(err));
    setSaving(false);
  }
}
